import { useEffect, useMemo, useState } from "react";
import { fetchProducts } from "@/lib/api";

export default function ProductsPage() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState("All");
  const [search, setSearch] = useState("");
  useEffect(() => {
    let active = true;
    fetchProducts()
      .then((data) => active && setProducts(data))
      .catch(() => active && setProducts([]))
      .finally(() => active && setLoading(false));
    return () => {
      active = false;
    };
  }, []);

  const categories = useMemo(() => {
    const set = new Set(products.map((p) => p.category));
    return ["All", ...Array.from(set)];
  }, [products]);

  const visible = useMemo(
    () =>
      activeCategory === "All"
        ? products
        : products.filter((p) => p.category === activeCategory),
    [products, activeCategory]
  );

  return (
    <div data-testid="products-page" className="bg-brand-ivory">
      <section className="bg-brand-cream border-b border-brand-border">
        <div className="max-w-7xl mx-auto px-6 lg:px-10 py-20 md:py-28 text-center">
          <span className="divider-ornament">Our Counter</span>
          <h1
            className="font-serif text-brand-maroon text-5xl sm:text-6xl lg:text-7xl mt-5"
            data-testid="products-title"
          >
            The Mithai Menu
          </h1>
          <p className="mt-6 max-w-2xl mx-auto text-brand-text/75 leading-relaxed">
            From syrup-soaked classics to ghee-rich fudges, every sweet here is
            handmade in small batches at our heritage kitchen.
          </p>
        </div>
      </section>

      <section className="border-b border-brand-border bg-brand-ivory sticky top-20 z-30">
        <div className="max-w-7xl mx-auto px-6 lg:px-10 py-5 flex flex-wrap gap-2 justify-center">
          {categories.map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setActiveCategory(cat)}
              className={`px-5 py-2 rounded-sm uppercase text-[11px] tracking-[0.22em] font-medium transition-colors border ${
                activeCategory === cat
                  ? "bg-brand-maroon text-brand-ivory border-brand-maroon"
                  : "bg-transparent text-brand-text/70 border-brand-border hover:border-brand-maroon hover:text-brand-maroon"
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </section>

      <section className="max-w-7xl mx-auto px-6 lg:px-10 py-20">
        {loading ? (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
            {Array.from({ length: 6 }).map((_, i) => (
              <div
                key={i}
                className="aspect-[4/5] bg-brand-cream border border-brand-border rounded-sm animate-pulse"
              />
            ))}
          </div>
        ) : visible.length === 0 ? (
          <p className="text-center text-brand-text/70 py-20">
            No sweets in this category at the moment.
          </p>
        ) : (
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-12">
            {visible.map((p) => (
              <article key={p.id} className="group flex flex-col">
                <div className="aspect-[4/5] overflow-hidden bg-brand-cream rounded-sm border border-brand-border">
                  <img
                    src={p.image_url}
                    alt={p.name}
                    loading="lazy"
                    className="h-full w-full object-cover group-hover:scale-105 transition-transform duration-700"
                  />
                </div>
                <div className="pt-5 flex items-start justify-between gap-4">
                  <div>
                    <div className="text-[10px] tracking-[0.3em] uppercase text-brand-gold mb-1.5">
                      {p.category}
                    </div>
                    <h3 className="font-serif text-2xl text-brand-text">
                      {p.name}
                    </h3>
                  </div>
                  <div className="text-right shrink-0">
                    <div className="font-serif text-2xl text-brand-maroon">
                      ₹{p.price_inr}
                    </div>
                    <div className="text-[10px] tracking-[0.25em] uppercase text-brand-text/60">
                      {p.unit}
                    </div>
                  </div>
                </div>
                <p className="mt-3 text-sm text-brand-text/75 leading-relaxed">
                  {p.description}
                </p>
              </article>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
